<script setup lang="ts">import {ref} from 'vue';import * as api from '../api/dictionaries';import {useResource} from '../hooks/useResource';import {refreshResources} from '../stores/resources';import {user} from '../stores/session';import PageTitle from '../components/common/PageTitle.vue';import Notice from '../components/common/Notice.vue';const{data,error}=useResource(api.list,[]);const name=ref('新展触点编码册'),entries=ref('A=序厅\nB=主展厅\nC=体验室'),message=ref('');async function submit(){try{await api.create({name:name.value,entries:entries.value.split('\n').filter(Boolean).map(line=>{const at=line.indexOf('=');if(at<1)throw new Error('每行须为CODE=名称');return {code:line.slice(0,at).trim(),label:line.slice(at+1).trim()}})});refreshResources();message.value=''}catch(e:any){message.value=e.message}}</script><template><PageTitle chapter="03" title="用一致的编码，留下不同的触达" description="每本编码册2—8个触点。编码唯一且大写，路径导入时与这本编码册逐项校验。"/><Notice :error="error||message"/><div class="editorial-grid"><section class="paper"><article v-for="d in data" :key="d.id" class="dictionary-record"><h2>{{d.name}}</h2><div class="dictionary-list"><div v-for="e in d.entries" :key="e.code"><code>{{e.code}}</code><b>{{e.label}}</b></div></div></article></section><form v-if="user?.role!=='viewer'" class="paper vertical-form" @submit.prevent="submit"><h2>建立新编码册</h2><label>编码册名称<input aria-label="编码册名称" v-model="name"/></label><label>每行 CODE=名称<textarea v-model="entries"/></label><button class="primary">保存触点编码册</button></form></div></template>
